import sys
import types

try:
    import concurrent.interpreters as interpreters
except ImportError:
    # Fallback for Python builds without PEP 734 support: emulate the API
    import concurrent

    class _Interpreter:
        def __init__(self):
            self._ns = {"__name__": "__main__"}
            self._closed = False

        def prepare_main(self, ns=None, /, **kwargs):
            if ns:
                self._ns.update(ns)
            self._ns.update(kwargs)

        def exec(self, code):
            exec(code, self._ns)

        def close(self):
            self._closed = True
            self._ns = {}

    shim = types.ModuleType("concurrent.interpreters")
    shim.create = _Interpreter
    sys.modules["concurrent.interpreters"] = shim
    concurrent.interpreters = shim
    interpreters = shim

interp = interpreters.create()
interp.prepare_main(n=10)
interp.exec('import math; print(math.factorial(n))')
interp.close()
